D={
81028:("Abrir uma história","Histórias começam com **Once upon a time** e avançam com **One day**. Para apresentar, use **there was / there were**.",[("{{Once upon a time}}, there was a girl.","Era uma vez uma menina."),("{{There was}} a big castle.","Havia um castelo grande."),("{{One day}}, a stranger came.","Um dia, um estranho chegou."),("The girl {{opened}} the door.","A menina abriu a porta.")],"Qual expressão abre um conto?",["Once upon a time","Next to the end","Last of all"],0,"Once upon a time equivale ao nosso “era uma vez”."),
920004:("Comparar com -er e more","Adjetivo curto leva **-er**; longo leva **more**. Os dois pedem **than**: *bigger than, more patient than*.",[("It is {{bigger than}} me.","É maior do que eu."),("This phone is {{faster than}} that one.","Este celular é mais rápido do que aquele."),("A teacher is {{more patient than}} a phone.","Um professor é mais paciente do que um celular."),("This is {{better than}} that.","Isto é melhor do que aquilo.")],"Qual está certa?",["more fast than","faster than","fastest than"],1,"Fast é curto: faster than."),
30032:("Comparar com -er than","Para comparar, junte **-er** ao adjetivo curto e use **than**. Se termina em vogal + consoante, dobre: *big → bigger*. Exceção: *good → better*.",[("The florist is {{smaller than}} the bookstore.","A floricultura é menor que a livraria."),("This street is {{quieter than}} that one.","Esta rua é mais tranquila que aquela."),("The laundry is {{bigger than}} the barber.","A lavanderia é maior que o barbeiro."),("The bakery is {{better than}} the grocery.","A padaria é melhor que o mercado.")],"Qual é o comparativo de “big”?",["biger","bigger","more big"],1,"Big termina em vogal + consoante: dobra o g."),
70064:("Comparar: better, faster","Comparativos curtos: **-er than**. Casos especiais: *good → better, bad → worse*. Para algo que custa pouco: *cheaper*.",[("The train is {{slower than}} the bus.","O trem é mais lento que o ônibus."),("This one is {{cheaper}}, but that one is {{better}}.","Este é mais barato, mas aquele é melhor."),("The test was {{easier than}} I thought.","A prova foi mais fácil do que pensei."),("Today is {{worse than}} yesterday.","Hoje está pior do que ontem.")],"Qual é o comparativo de “bad”?",["badder","worse","more bad"],1,"Bad é irregular: worse."),
81029:("used to: infância","**Used to** + verbo base conta hábitos do passado que já acabaram: *I used to play outside*.",[("I {{used to play}} outside.","Eu costumava brincar lá fora."),("We {{used to climb}} trees.","Costumávamos subir em árvores."),("{{Did you use to}} play outside?","Você costumava brincar lá fora?"),("I had a toy I loved.","Eu tinha um brinquedo de que gostava.")],"“I used to swim” quer dizer…",["Eu nado agora.","Eu nadava antes.","Eu vou nadar."],1,"Used to fala de um hábito que ficou no passado."),
81030:("used to be: antes e agora","**Used to be** mostra como era antes. **Now** mostra como é hoje.",[("It {{used to be}} quiet.","Costumava ser tranquilo."),("{{Now}} it is crowded.","Agora está lotado."),("We {{lived}} downtown.","Morávamos no centro."),("The street {{changed}} a lot.","A rua mudou muito.")],"Qual frase compara antes e agora?",["It was quiet, now.","It used to be quiet. Now it is loud.","It will be loud."],1,"Used to be (antes) + now (hoje) formam o contraste."),
81031:("ago: há quanto tempo","**Ago** vem depois do tempo e pede verbo no **passado**: *two hours ago, a week ago*.",[("I lost my wallet {{two hours ago}}.","Perdi minha carteira há duas horas."),("It was in my pocket {{a week ago}}.","Estava no bolso há uma semana."),("I {{lost}} the card {{three days ago}}.","Perdi o cartão há três dias."),("{{When}} did you lose it?","Quando você a perdeu?")],"Como dizer “há três dias”?",["ago three days","three days ago","three ago days"],1,"Ago fica depois da expressão de tempo."),
81032:("tell / say / ask","**Tell** + pessoa: *tell me the truth*. **Say** + palavras: *say hello*. **Ask** + pergunta: *ask a question*.",[("{{Tell}} me the truth.","Diga-me a verdade."),("She {{says}} hello.","Ela diz olá."),("Can I {{ask}} you a question?","Posso fazer uma pergunta?"),("He {{told}} us a lie.","Ele nos contou uma mentira.")],"Complete: “Please ___ me your name.”",["say","tell","speak"],1,"Tell pede uma pessoa logo depois: tell me."),
81033:("first, then, after that","Para contar em ordem: **First, Then, After that, Finally** — com verbos no passado.",[("{{First}}, I met the teacher.","Primeiro, conheci a professora."),("{{Then}}, I sat down.","Depois, sentei."),("{{After that}}, we read a book.","Depois disso, lemos um livro."),("{{Finally}}, we went home.","Por fim, fomos para casa.")],"Qual palavra fecha a sequência?",["First","Then","Finally"],2,"Finally marca o último passo."),
81034:("Contar o dia","Conte o dia com **First, Then, After that** e ligue ideias com **and** e **but**.",[("{{First}}, I met my boss.","Primeiro, conheci meu chefe."),("{{Then}}, I had a meeting.","Depois, tive uma reunião."),("{{After that}}, I had a coffee break.","Depois, fiz uma pausa para o café."),("He came late, {{but}} he was kind.","Ele chegou tarde, mas foi gentil.")],"Qual palavra ligue duas ideias contrárias?",["and","but","then"],1,"But liga ideias que se opõem."),
81035:("because × so","**Because** dá o motivo; **so** dá o resultado: *I missed the bus, so I was late.*",[("I was late {{because}} I missed the bus.","Cheguei tarde porque perdi o ônibus."),("I missed the bus, {{so}} I was late.","Perdi o ônibus, então cheguei tarde."),("It rained a lot, {{so}} I stayed home.","Choveu muito, então fiquei em casa."),("I stayed home {{because}} it rained.","Fiquei em casa porque choveu.")],"Complete: “It was cold, ___ I wore a coat.”",["because","so","but"],1,"O frio é o motivo; vestir o casaco é o resultado: so."),
920005:("Superlativo: the best","O superlativo leva **the**: adjetivo curto + **-est**, longo com **most**.",[("This is {{the best}} place.","Este é o melhor lugar."),("He is {{the tallest}} in the group.","Ele é o mais alto do grupo."),("It is {{the most expensive}} in my class.","É o mais caro da minha turma."),("She is {{the smartest}} chef here.","Ela é a chef mais inteligente daqui.")],"Como dizer “o mais caro”?",["the expensivest","the most expensive","the more expensive"],1,"Expensive é longo: the most expensive."),
81036:("Passado positivo","Para contar o que deu certo: **passed, won, went well**. *Win* é irregular: win → won.",[("I {{passed}} the test.","Passei na prova."),("We {{won}} the game.","Ganhamos o jogo."),("Everything {{went well}}.","Tudo correu bem."),("I felt {{proud}}.","Senti orgulho.")],"Qual é o passado de “win”?",["winned","won","wan"],1,"Win é irregular: won."),
81037:("Is / Are included?","Para perguntar o que o aluguel cobre: **Is water included? Are bills included?** Resposta: *Yes, it is. / No, it isn't.*",[("{{Is water included}}?","A água está incluída?"),("{{Are bills included}}?","As contas estão incluídas?"),("Yes, it {{is}}.","Sim, está."),("No, it {{isn't}}. You pay the deposit.","Não. Você paga o depósito.")],"“Is the internet included?” pergunta…",["se a internet está no preço","se a internet é rápida","onde fica a internet"],0,"Included = incluído no preço."),
81038:("Could you…?","Para pedidos educados: **Could you** + verbo. Respostas: *Of course. / Sure.*",[("{{Could you}} send someone?","Você poderia mandar alguém?"),("{{Could you}} check the bill?","Você poderia conferir a conta?"),("There is a leak in the kitchen.","Há um vazamento na cozinha."),("{{Of course}}. I'll call today.","Claro. Ligo hoje.")],"Qual pedido é mais educado?",["Check the bill!","Could you check the bill?","You check the bill."],1,"Could you suaviza o pedido."),
81039:("Frequência","O advérbio vem **antes** do verbo: *I always drink coffee*. Com **be**, vem **depois**: *He is always late*.",[("I {{always}} drink coffee.","Eu sempre tomo café."),("She {{usually}} walks to work.","Ela geralmente vai a pé ao trabalho."),("He {{never}} drinks tea.","Ele nunca toma chá."),("He is {{always}} late.","Ele está sempre atrasado.")],"Qual está certa?",["She is never late.","She never is late.","She is late never."],0,"Com be, o advérbio vem depois: is never."),
81040:("once, twice, three times","**Once** = uma vez; **twice** = duas; depois *three times, four times*. Use com *a week / a month*.",[("I go {{once}} a week.","Vou uma vez por semana."),("She swims {{twice}} a week.","Ela nada duas vezes por semana."),("We run {{three times}} a week.","Corremos três vezes por semana."),("How {{often}} do you swim?","Com que frequência você nada?")],"Como dizer “duas vezes por mês”?",["twice a month","two time a month","second a month"],0,"Twice = duas vezes."),
81041:("used to live","**Used to live in/at** + lugar: um lugar onde você já morou e não mora mais.",[("We {{used to live}} in a cabin.","Morávamos numa cabana."),("She {{used to live}} near a lake.","Ela morava perto de um lago."),("There {{was}} a lake near the house.","Havia um lago perto da casa."),("We {{had}} one horse.","Tínhamos um cavalo.")],"“We used to live there” significa…",["Moramos lá agora.","Moramos lá antes.","Vamos morar lá."],1,"Used to = antes, mas não mais."),
81042:("Antes e agora","Compare: **used to + verbo** (antes) e **now + presente** (hoje).",[("We {{used to write}} letters.","Costumávamos escrever cartas."),("{{Now}} we send messages.","Agora mandamos mensagens."),("Trains are {{faster}} now.","Os trens estão mais rápidos agora."),("People {{used to}} wait a lot.","As pessoas esperavam muito.")],"Qual frase fala do presente?",["We used to call.","Now we text.","We called."],1,"Now + presente mostra o hoje."),
80310:("used to + verbo","Para um hábito do passado, **used to** + verbo base: *We used to play with marbles.*",[("I {{used to swim}} in the river.","Eu costumava nadar no rio."),("We {{used to play}} with marbles.","Brincávamos de bolinha de gude."),("Leo {{was}} my best friend.","O Leo era meu melhor amigo."),("We {{built}} a treehouse.","Construímos uma casa na árvore.")],"Qual está certa?",["I used to swimming.","I used to swim.","I use to swim."],1,"Depois de used to, o verbo fica no básico."),
920006:("will e won't","**Will** não muda com he, she ou it: *She will come*. Negativa: **won't**.",[("Robots {{will clean}} our homes.","Robôs vão limpar nossas casas."),("I {{won't forget}} tomorrow.","Não vou esquecer amanhã."),("{{Will you come}} tomorrow?","Você virá amanhã?"),("She {{will}} travel to Mars.","Ela vai viajar a Marte.")],"Qual está certa?",["She wills go.","She will go.","She will goes."],1,"Will + verbo base, sem -s."),
81043:("if + will","Condição possível: **if + presente**, **will + verbo**. *If it rains, I will stay home.*",[("{{If}} it rains, I {{will stay}} home.","Se chover, ficarei em casa."),("I {{will take}} an umbrella.","Levarei um guarda-chuva."),("If it is sunny, we {{will go out}}.","Se fizer sol, sairemos."),("What {{will}} you do?","O que você fará?")],"Qual está certa?",["If it will rain, I stay.","If it rains, I will stay.","If it rains, I stay will."],1,"Depois do if, use o presente (rains); o will fica na outra parte."),
81044:("will: previsões","Para prever: **will** + verbo. Reforce com **probably** ou **maybe**.",[("It {{will be}} sunny.","Vai fazer sol."),("Our team {{will win}}.","Nosso time vai ganhar."),("She {{will probably}} come.","Ela provavelmente virá."),("{{Maybe}} it will rain tomorrow.","Talvez chova amanhã.")],"Onde fica “probably”?",["will probably come","probably will to come","will come probably to"],0,"Probably vem logo depois de will."),
81045:("Fatos com if","Para fatos: **if + presente, presente**. *If you heat ice, it melts.*",[("If you heat ice, it {{melts}}.","Se você esquenta gelo, ele derrete."),("If you heat water, it {{boils}}.","Se você esquenta água, ela ferve."),("If you freeze water, it {{turns}} to ice.","Se você congela água, ela vira gelo."),("{{If}} you add heat, things change.","Se você acrescenta calor, as coisas mudam.")],"Complete: “If you freeze water, it ___ to ice.”",["will turns","turns","turned"],1,"Fato científico: presente nos dois lados."),
81047:("So do I / Neither do I","Concordar com algo **positivo**: *So do I.* Com algo **negativo**: *Neither do I.* O verbo acompanha a primeira frase.",[("I like pizza. {{So do I}}.","Gosto de pizza. Eu também."),("I don't like fish. {{Neither do I}}.","Não gosto de peixe. Nem eu."),("I am tired. {{So am I}}.","Estou cansado. Eu também."),("I can't swim. {{Neither can I}}.","Não sei nadar. Nem eu.")],"Complete: “I don't eat meat.” — “___ do I.”",["So","Neither","Too"],1,"Frase negativa: neither."),
81048:("too e enough","**Too + adjetivo** = demais: *too hot*. **Adjetivo + enough** = suficiente: *big enough*.",[("The soup is {{too hot}}.","A sopa está quente demais."),("The bed is {{big enough}}.","A cama é grande o bastante."),("This chair is {{too small}}.","Esta cadeira é pequena demais."),("This one is {{just right}}.","Esta é a ideal.")],"Qual frase diz que algo não basta?",["It is too big.","It is not big enough.","It is very big."],1,"Not enough = insuficiente."),
80207:("too much / too many","Coisas que **não se contam**: *too much sugar*. Coisas que **se contam**: *too many donuts*.",[("There is {{too much}} sugar.","Há açúcar demais."),("There are {{too many}} crumbs.","Há migalhas demais."),("Don't eat {{too much}} chocolate.","Não coma chocolate demais."),("I ate {{too many}} waffles!","Comi waffles demais!")],"Complete: “Too ___ donuts!”",["much","many","more"],1,"Donuts se contam: too many."),
81049:("the + adjetivo-est","Para o topo: **the + adjetivo-est**. Irregulares: *the best, the worst*.",[("He is {{the tallest}} man.","Ele é o homem mais alto."),("This is {{the biggest}} cake.","Este é o maior bolo."),("That was {{the worst}} movie.","Aquele foi o pior filme."),("She is {{the oldest}}, and he is {{the best}}.","Ela é a mais velha, e ele é o melhor.")],"Qual é o superlativo de “bad”?",["the baddest","the worst","the most bad"],1,"Bad é irregular: the worst."),
30040:("the oldest, the youngest","Para o mais … de todos: **the + adjetivo-est**. Adjetivos longos usam **the most**. Pergunta: **Who is the oldest?**",[("{{Who is the oldest}}?","Quem é o mais velho?"),("My grandmother is {{the oldest}}.","Minha avó é a mais velha."),("My newborn nephew is {{the youngest}}.","Meu sobrinho recém-nascido é o mais novo."),("She is {{the most important}} person.","Ela é a pessoa mais importante.")],"Como dizer “o mais novo”?",["the most young","the youngest","the youngerest"],1,"Young é curto: the youngest."),
70080:("the most / the -est","**The + -est** para adjetivos curtos (*the oldest*) e **the most** para longos (*the most helpful*).",[("Who is {{the oldest}}?","Quem é o mais velho?"),("Leo is {{the youngest}} at the table.","O Leo é o mais novo à mesa."),("Grandma is {{the most generous}}.","A vovó é a mais generosa."),("Pull up a chair!","Puxe uma cadeira!")],"Qual está certa?",["the most kind","the kindest","the more kind"],1,"Kind é curto: the kindest."),
}
